UPDATE calendar_nodes SET doc_json=json_insert(doc_json,'$.items[#]',json('{"key":"unified_exam","name":"统考","months":[12],"note":"按省份改"}')) WHERE tenant_id IN(SELECT tenant_id FROM tenant_subjects WHERE id='music_exam') AND NOT EXISTS(SELECT 1 FROM json_each(calendar_nodes.doc_json,'$.items') WHERE json_extract(value,'$.key')='unified_exam');
